mapper.select:
SELECT i.WF_INSTANCE_ID, i.WORKFLOW_ID, d.WORKFLOW_NAME, i.START_DATE, i.END_DATE, i.ERROR_FLAG, i.STATUS, i.ERROR_MESSAGE, i.PWF_INSTANCE_ID, i.TPWF_INSTANCE_ID, CASE WHEN EXISTS ( SELECT 1 FROM task_instances ti WHERE ti.WF_INSTANCE_ID = i.WF_INSTANCE_ID AND ti.STATUS IN ('ERROR', 'TIMEOUT','CANCELED') ) THEN 'Y' ELSE 'N' END AS TASK_ERROR_FLAG FROM WF_INSTANCES i LEFT JOIN WF_DEFINITIONS d ON i.WORKFLOW_ID = d.WORKFLOW_ID
AND i.WORKFLOW_ID LIKE #{workflowId}
AND d.WORKFLOW_NAME LIKE #{workflowName}
AND i.WF_INSTANCE_ID LIKE #{wfInstanceId}
AND i.PWF_INSTANCE_ID LIKE #{parentWfInstanceId}
AND i.TPWF_INSTANCE_ID LIKE #{topParentInstanceId}
AND STATUS = #{status}
AND START_DATE >= #{startDateFrom}
AND START_DATE <= #{startDateTo}

mapper.update:
UPDATE WF_INSTANCES
SET
    END_DATE = #{endDate},
    STATUS = #{status}
WHERE
    WF_INSTANCE_ID = #{wfInstanceId}
